# -*- coding: utf-8 -*-

import xbmc
from torrserve_stream.overlay import Overlay


class xPlayer(xbmc.Player):
    def __init__(self, hash=None, index=None):
        ''' index: 0-based file index '''
        self.tsserv = None
        self.hash = hash
        self.index = index
        self.active = True
        self.started = False
        self.ended = False
        self.paused = False
        self.buffering = False
        self._overlay = None
        xbmc.Player.__init__(self)
        self.onPlayBackStarted()

    def onPlayBackPaused(self):
        self.paused = True
        if self.hash is not None:
            self._overlay = Overlay(hash=self.hash, index=self.index)
            self._overlay.show()
            while xbmc.Player().isPlaying() and self.paused:
                self._overlay.update()
                xbmc.sleep(800)
            if self._overlay:
                self._overlay.hide()
                self._overlay = None

    def onPlayBackStarted(self):
        self._hide_overlay()

    def onPlayBackResumed(self):
        self.paused = False
        self._hide_overlay()

    def onPlayBackStopped(self):
        self.paused = False
        self._hide_overlay()

    def __del__(self):
        self.paused = False
        self._hide_overlay()

    def _hide_overlay(self):
        if self._overlay:
            self._overlay.hide()
            self._overlay = None
